action.code:
if (head == nullptr) return false;
ListNode* prev = nullptr;
ListNode* curr = head;
while (curr != nullptr && curr->value != value) {
    prev = curr;
    curr = curr->next;
}
if (curr == nullptr) return false;
if (prev == nullptr) {
    head = curr->next;
} else {
    prev->next = curr->next;
}
delete curr;
return true;

